#include "json.hpp"
#include <openssl/bn.h>
#include <openssl/ec.h>
#include <openssl/obj_mac.h>
#include <openssl/sha.h>
#include <iomanip>
#include <iostream>
#include <map>
#include <memory>
#include <tuple>
static void check(bool x,const char*m){if(!x)throw std::runtime_error(m);}
static std::string hash_bytes(const std::string&s){unsigned char h[SHA256_DIGEST_LENGTH];SHA256(reinterpret_cast<const unsigned char*>(s.data()),s.size(),h);std::ostringstream o;for(auto c:h)o<<std::hex<<std::setw(2)<<std::setfill('0')<<int(c);return o.str();}
static std::string expected(const std::string&curve,const std::string&panel,int index,const std::string&scalar,const std::string&order){
 int nid=curve=="P-384"?NID_secp384r1:NID_secp521r1;std::unique_ptr<EC_GROUP,decltype(&EC_GROUP_free)>g(EC_GROUP_new_by_curve_name(nid),EC_GROUP_free);std::unique_ptr<BN_CTX,decltype(&BN_CTX_free)>ctx(BN_CTX_new(),BN_CTX_free);check(g&&ctx,"backend allocation");BIGNUM*k=BN_new(),*mu=nullptr,*n=nullptr,*actual=BN_new();check(k&&actual&&BN_dec2bn(&mu,scalar.c_str())>0&&BN_dec2bn(&n,order.c_str())>0,"scalars");check(EC_GROUP_get_order(g.get(),actual,ctx.get())&&BN_cmp(actual,n)==0,"group order");std::string seed="cm-marked-scalar-v1:"+panel+":"+curve+":"+std::to_string(index);unsigned char bytes[SHA256_DIGEST_LENGTH];SHA256(reinterpret_cast<const unsigned char*>(seed.data()),seed.size(),bytes);check(BN_bin2bn(bytes,sizeof(bytes),k)&&BN_nnmod(k,k,n,ctx.get()),"input law");if(BN_is_zero(k))check(BN_one(k),"nonzero input");std::unique_ptr<EC_POINT,decltype(&EC_POINT_free)>P(EC_POINT_new(g.get()),EC_POINT_free),Y(EC_POINT_new(g.get()),EC_POINT_free);check(P&&Y,"point allocation");check(EC_POINT_mul(g.get(),P.get(),k,nullptr,nullptr,ctx.get()),"input generation");check(EC_POINT_mul(g.get(),Y.get(),nullptr,P.get(),mu,ctx.get()),"independent scalar replay");size_t size=EC_POINT_point2oct(g.get(),Y.get(),POINT_CONVERSION_COMPRESSED,nullptr,0,ctx.get());std::vector<unsigned char>out(size);check(size&&EC_POINT_point2oct(g.get(),Y.get(),POINT_CONVERSION_COMPRESSED,out.data(),size,ctx.get())==size,"output encoding");std::ostringstream encoded;for(auto c:out)encoded<<std::hex<<std::setw(2)<<std::setfill('0')<<int(c);BN_free(k);BN_free(mu);BN_free(n);BN_free(actual);return encoded.str();
}
int main(int argc,char**argv){try{check(argc==3,"replay FIXTURE_DIR ROWS");auto c=read_json(std::string(argv[1])+"/published-curves.json"),m=read_json(std::string(argv[1])+"/marked-relations.json");std::map<std::string,std::string>orders,scalars;for(auto&j:c.at("rows").array)orders[j.at("name").str()]=j.at("n").str();for(auto&j:m.at("rows").array)scalars[j.at("name").str()]=j.at("mu").str();std::ifstream f(argv[2]);check(bool(f),"rows file");std::ostringstream raw;raw<<f.rdbuf();auto text=raw.str();std::istringstream lines(text);std::string line;std::map<std::tuple<std::string,std::string,int>,std::string>cache;unsigned rows=0;while(std::getline(lines,line)){auto j=JsonParser(line).read();auto curve=j.at("curve").str(),panel=j.at("panel").str();int index=j.at("point").integer();check(orders.count(curve)&&scalars.count(curve),"unknown curve");check((panel=="heldout"||panel=="calibration")&&index>=0&&index<32,"point identity");auto key=std::make_tuple(curve,panel,index);if(!cache.count(key))cache[key]=expected(curve,panel,index,scalars.at(curve),orders.at(curve));check(j.at("output").str()==cache.at(key),"independent output mismatch");++rows;}check(rows>0,"empty replay");std::cout<<"{\"independent_point_replay_pass\":true,\"rows\":"<<rows<<",\"distinct_points\":"<<cache.size()<<",\"rows_sha256\":\""<<hash_bytes(text)<<"\"}"<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<"point replay refused: "<<e.what()<<std::endl;return 1;}}
